<?php $l="%$s%";foreach(q("SELECT c.*,(SELECT COUNT(*) FROM reservations r WHERE r.customer_id=c.customer_id) n,a.agreement_id,a.renter_signed_at,a.staff_signed_at FROM customers c JOIN users u ON u.user_id=c.user_id JOIN roles ro ON ro.role_id=u.role_id AND ro.role_name='Customer' LEFT JOIN rental_agreements a ON a.agreement_id=(SELECT aa.agreement_id FROM rental_agreements aa WHERE aa.customer_id=c.customer_id ORDER BY aa.agreement_id DESC LIMIT 1) WHERE CONCAT(c.first_name,' ',c.last_name,c.phone,IFNULL(c.email,''),IFNULL(c.identification_number,'')) LIKE ? ORDER BY c.customer_id DESC",[$l])->fetchAll() as $x):?><tr><td><?=e($x['customer_code'])?><td><?=e($x['first_name'].' '.$x['last_name'])?><br><small class="text-muted"><?=e($x['email'])?></small><td><?=e($x['phone'])?><td><?=e($x['identification_number'])?><td><?=e($x['driving_license_number'])?> <small>(<?=e($x['license_expiry_date'])?>)</small><td><?=$x['n']?><td><?=badge($x['status'])?><td><?php if($x['agreement_id']):?><a class="btn btn-sm btn-outline-primary" href="<?=BASE?>shared/agreement.php?id=<?=$x['agreement_id']?>">Open</a><?php if($x['renter_signed_at']&&$x['staff_signed_at']):?> <a class="btn btn-sm btn-outline-secondary" href="<?=BASE?>shared/agreement_download.php?id=<?=$x['agreement_id']?>">PDF</a><?php endif;?><?php else:?>—<?php endif;?>
<?php if($can):?><td><form method="post" class="d-flex gap-1"><?=csrf_f()?><input type="hidden" name="id" value="<?=$x['customer_id']?>"><select name="status" class="form-select form-select-sm w-auto"><?php foreach(['active','inactive','blacklisted'] as $o)echo '<option'.($o===$x['status']?' selected':'').'>'.$o.'</option>';?></select><input name="notes" value="<?=e($x['notes'])?>" placeholder="Notes" class="form-control form-control-sm"><button class="btn btn-sm btn-outline-primary">Save</button></form><?php endif;?></tr><?php endforeach;?></table></div></div><?php foot();
